/**
 * Alien-language vocabulary metadata, generated from the game data word
 * table (NMSE Words.json dump of the in-game dictionary). Do not edit by
 * hand — regenerate against a newer dump when a game update adds words.
 *
 * The save stores learned word *groups* (KnownWordGroups), which is also
 * the unit the game's "words learned" counter displays (verified in-game:
 * 155 known groups shows as "155 words"). A group can additionally unlock
 * variant dictionary words (e.g. ^WAR_ABANDON teaches both "abandon" and
 * "abandoned"); most unlock exactly one, so only the exceptions are listed.
 */

export type LanguageName = 'Gek' | "Vy'keen" | 'Korvax' | 'Atlas' | 'Autophage'

/** Save race index -> language whose words that race teaches. */
export const RACE_LANGUAGES: Record<number, LanguageName> = {
  0: 'Gek',
  1: "Vy'keen",
  2: 'Korvax',
  4: 'Atlas',
  8: 'Autophage'
}

/** Learnable vocabulary sizes per language, in words and word groups. */
export const LANGUAGE_TOTALS: Record<LanguageName, { words: number; groups: number }> = {
  'Gek': { words: 1158, groups: 922 },
  "Vy'keen": { words: 1164, groups: 931 },
  'Korvax': { words: 1100, groups: 860 },
  'Atlas': { words: 262, groups: 223 },
  'Autophage': { words: 1136, groups: 889 }
}

